hints:
```
build Union-Find from connections
for each station i in 1..c:
    insert i into its component's ordered set
for each query [type, x]:
    if type == 1:
        if x is online: answer x
        else if component set non-empty: answer smallest element
        else: answer -1
    if type == 2:
        remove x from its component's set
        mark x offline
```

code.cpp:
class Solution {
    vector<int> parent, rank_;

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return;
        if (rank_[px] < rank_[py]) swap(px, py);
        parent[py] = px;
        if (rank_[px] == rank_[py]) rank_[px]++;
    }

public:
    vector<int> processQueries(int c, vector<vector<int>>& connections, vector<vector<int>>& queries) {
        parent.resize(c + 1);
        rank_.resize(c + 1, 0);
        for (int i = 0; i <= c; i++) parent[i] = i;

        for (auto& conn : connections) {
            unite(conn[0], conn[1]);
        }

        unordered_map<int, set<int>> compSets;
        for (int i = 1; i <= c; i++) {
            int root = find(i);
            compSets[root].insert(i);
        }

        vector<bool> online(c + 1, true);

        vector<int> result;
        for (auto& q : queries) {
            int type = q[0], x = q[1];
            int root = find(x);
            if (type == 1) {
                if (online[x]) {
                    result.push_back(x);
                } else {
                    auto& s = compSets[root];
                    if (s.empty()) {
                        result.push_back(-1);
                    } else {
                        result.push_back(*s.begin());
                    }
                }
            } else {
                if (online[x]) {
                    online[x] = false;
                    compSets[root].erase(x);
                }
            }
        }

        return result;
    }
};
